expect(response.status()).toBe(201);
const transfer = await response.json();
const reference = transfer.id;
expect(transfer.amountMinor).toBe(10000);
expect(transfer.sourceAccountId).toBe(lab.sourceAccountId);

const projected = await page.request.get(
  '/api/ledger/transfers',
  { params: { sourceAccountId: lab.sourceAccountId } }
);
expect(projected.status()).toBe(200);

await expect.poll(async () => {
  const r = await page.request.get('/api/ledger/transfers', {
    params: { sourceAccountId: lab.sourceAccountId },
  });
  if (r.status() !== 200) return false;
  const body = await r.json();
  return body.items.some(item => item.id === reference);
}, { timeout: 5000 }).toBe(true);
